import{z as o,x as s,o as l,c as m,q as B,j as i,D as e,d as a,s as n,S as r,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"边缘多模态","description":"","frontmatter":{"title":"边缘多模态","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-edge-multimodal.md","filePath":"llm/mm-edge-multimodal.md","lastUpdated":1791413859000}'),d={name:"llm/mm-edge-multimodal.md"};function p(D,E,C,u,h,f){const t=s("Mermaid");return l(),m("div",null,[E[2]||(E[2]=B('<h1 id="边缘多模态" tabindex="-1">边缘多模态 <a class="header-anchor" href="#边缘多模态" aria-label="Permalink to &quot;边缘多模态&quot;">​</a></h1><div class="epigraph"><p>云上谈利用率，端上谈配额：内存给多少、电池给多少，模型只能在这些数字里挑自己能做的事。</p><footer>—— 据 llama.cpp 端侧推理实践与端云协同系统文献整理</footer></div><p><a href="/llm/mm-multimodal-speculative">上一课</a>按内容开关投机；云上那些旋钮——分池、扩容、驱逐——在端侧全部失效，手机、车机、眼镜给的不是机房，是一份内存与功耗配额。端侧 LLM 的通用实践（<a href="/llm/llamacpp">llama.cpp</a>）与<a href="/llm/edge-cloud-split">端云协同</a>的分工已各有专课，本课只写多模态压上去之后改了什么：编码器挤进内存账、相机流变成持续功耗、以及「什么时候必须上云」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内存是第一道墙。3B 级语言模型 int4 权重约 2 GB，0.3–0.7B 的视觉编码器加投影再占零点几 GB，剩下给 KV、激活与运行时的空间在 8 GB 手机上常不足 4 GB——多模态会话的 KV 又比纯文本重一到两个量级（<a href="/llm/mm-multimodal-kv">多模态 KV 管理</a>），预算必须从内存账反推，而不是从上下文长度正推。第二道墙是功耗：端侧相机是持续流，编码器若逐帧常开，屏幕还没亮起回答，电池已经先掉一格。第三道墙是算子：NPU 工具链只支持覆盖好的算子集，编码器里一个不支持的归一化或重排，整段就得回退到更耗电的 CPU。</p><p><span class="marginnote">「int4 权重约 2 GB」这笔账可以自己算一遍：int4 是每个权重只存 16 个可能档位之一，合 0.5 字节一个数，3B 参数就是 \\(3\\times10^9 \\times 0.5\\) 字节 = 1.5 GB，加上量化刻度等开销约 1.8–2 GB。术语翻译：量化就是把高精度小数表「四舍五入」到粗档位换取体积——省的是内存和搬运时间，付的是精度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个动作按顺序做。<strong>减规模</strong>：语言模型压到 2–3B，编码器换同族小杯，先保证能住下；量化分级——LLM 权重走 int4（<a href="/llm/awq">AWQ</a> 一类激活感知口径），编码器 int8，激活按算子支持选精度，精度不是一刀切而是逐组件配额。<strong>节流</strong>：帧级调度是边缘多模态独有的节能层——低频跑一个轻量场景变化检测，画面没变就复用上一帧嵌入（<a href="/llm/mm-serving-vision-encoder">嵌入缓存</a>的省电版），变了才全功率编码；问答间隔长的会话把编码器整个下电。<strong>分工</strong>：端侧模型先答常见问题，置信低、要大上下文或要最新知识的请求带图上云，云的返回再落到端侧继续多轮。</p><p><span class="marginnote">一笔端侧账：3B int4 权重约 1.8–2 GB，ViT int8 约 0.3–0.5 GB，系统与运行时占走大头后，8 GB 设备留给 KV 与激活的常不足 4 GB——视觉 token 预算在端上不是服务质量参数，是内存红线。</span></p>',9)),(l(),i(r,null,{default:e(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAM%5B%22%E7%9B%B8%E6%9C%BA%E5%B8%A7%E6%B5%81%22%5D%20--%3E%20DET%7B%22%E5%9C%BA%E6%99%AF%E5%8F%98%E5%8C%96%E6%A3%80%E6%B5%8B%22%7D%0A%20%20DET%20--%3E%7C%E6%97%A0%E5%8F%98%E5%8C%96%7C%20REUSE%5B%22%E5%A4%8D%E7%94%A8%E4%B8%8A%E4%B8%80%E5%B8%A7%E5%B5%8C%E5%85%A5%22%5D%0A%20%20DET%20--%3E%7C%E5%8F%98%E5%8C%96%7C%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20int8%20%E7%BC%96%E7%A0%81%22%5D%0A%20%20REUSE%20--%3E%20LLM%5B%222%E2%80%933B%20LLM%20int4%20%E8%A7%A3%E7%A0%81%22%5D%0A%20%20ENC%20--%3E%20LLM%0A%20%20LLM%20--%3E%20CONF%7B%22%E7%BD%AE%E4%BF%A1%E4%B8%8E%E5%A4%8D%E6%9D%82%E5%BA%A6%3F%22%7D%0A%20%20CONF%20--%3E%7C%E5%8F%AF%E7%AD%94%7C%20ANS%5B%22%E7%AB%AF%E4%BE%A7%E4%BD%9C%E7%AD%94%22%5D%0A%20%20CONF%20--%3E%7C%E5%AD%98%E7%96%91%7C%20CLOUD%5B%22%E5%B8%A6%E5%9B%BE%E4%B8%8A%E4%BA%91%22%5D%0A%20%20CLOUD%20--%3E%20ANS%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("端侧解码与云侧的瓶颈分布不同。批为 1 时解码是纯 memory-bound：每步都要把权重从存储搬进计算单元，首 token 与吐字速度主要吃内存带宽，而不是算力——这让"),A("a",{href:"/llm/spec-edge"},"端侧投机"),a("从「可选优化」变成「常规操作」：小草稿多出几个 token，摊薄的正是最贵的权重搬运。节流的经济学同理：场景检测器自身的功耗必须比省下的编码低一个量级，所以它跑低分辨率、低帧率，宁可漏检一次，也不能让「省电层」变成耗电层。")],-1)),E[5]||(E[5]=A("p",null,[a("端云协同的判据落在置信度与上下文两端。端侧答不了的问题有两类：能力不够（细 OCR、复杂推理）与信息不够（知识过期、上下文超端侧窗口）。上传的不必是原图——按"),A("a",{href:"/llm/mm-visual-token-budget"},"视觉 token 预算"),a("压缩后再上行，省的是用户的流量与云的 prefill；云返回结果后，多轮状态留在端侧，后续追问不再上行。")],-1)),(l(),i(r,null,{default:e(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%89%B9%E4%B8%BA%201%EF%BC%9A%E6%AF%8F%E6%AD%A5%E7%93%B6%E9%A2%88%E9%83%BD%E6%98%AF%E6%90%AC%E6%9D%83%E9%87%8D%22%5D%20--%3E%20P%5B%22%E6%99%AE%E9%80%9A%E8%A7%A3%E7%A0%81%EF%BC%9A%E6%90%AC%E4%B8%80%E9%81%8D%E6%9D%83%E9%87%8D%E5%87%BA%E4%B8%80%E4%B8%AA%20token%22%5D%0A%20%20S%20--%3E%20SP%5B%22%E6%8A%95%E6%9C%BA%E8%A7%A3%E7%A0%81%EF%BC%9A%E6%90%AC%E4%B8%80%E9%81%8D%E6%9D%83%E9%87%8D%E9%AA%8C%E8%AF%81%E4%B8%80%E4%B8%B2%22%5D%0A%20%20P%20--%3E%20T1%5B%22%E9%80%9F%E5%BA%A6%E7%BA%A6%E7%AD%89%E4%BA%8E%E5%B8%A6%E5%AE%BD%E9%99%A4%E4%BB%A5%E6%9D%83%E9%87%8D%E4%BD%93%E7%A7%AF%22%5D%0A%20%20SP%20--%3E%20D%5B%22%E5%B0%8F%E8%8D%89%E7%A8%BF%E6%A8%A1%E5%9E%8B%E5%85%88%E7%8C%9C%20k%20%E4%B8%AA%20token%22%5D%0A%20%20D%20--%3E%20V%5B%22%E7%9B%AE%E6%A0%87%E6%A8%A1%E5%9E%8B%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%E9%AA%8C%E8%AF%81%20k%20%E4%B8%AA%22%5D%0A%20%20V%20--%3E%20T2%5B%22%E5%90%8C%E4%B8%80%E6%AC%A1%E6%90%AC%E8%BF%90%E6%91%8A%E5%87%BA%E5%A4%9A%E4%B8%AA%20token%22%5D%0A%20%20T1%20--%3E%20SAME%5B%22%E8%A2%AB%E6%8B%92%E7%9A%84%E8%8D%89%E7%A8%BF%E4%B8%8D%E4%BD%9C%E6%95%B0%EF%BC%8C%E6%AD%A3%E7%A1%AE%E6%80%A7%E4%B8%8D%E5%8F%98%22%5D%0A%20%20T2%20--%3E%20SAME%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">投机解码的直觉类比：请一位实习生（草稿模型）先快速口译一整句，主管（目标模型）只在最后对照原文一次性批改——批改比翻译快得多，因为校验可以并行。批得对的句子直接生效，批错的部分重说，所以答案质量跟主管亲自翻译完全一样，快的是「一次搬运出多个词」，不是降低标准。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>量化精度要按模态评测：编码器 int8 对「图里有什么」无损，对文档小字与二维码类的细结构可能致命，端侧 OCR 场景要么给编码器留 int8 以上的档位，要么把 OCR 路由上云。散热是隐形配额：连续视频问答几分钟后的热节流会把性能砍到与规格表对不上，容量测试必须含稳态段而不只跑冷启动。模型升级受存储与内存碎片约束，端上的「发布工程」是整套下架换装，不是改个配置。</p><p><span class="marginnote">常见误区：只跑 30 秒冷启动跑分就写测评。芯片像短跑运动员，冲刺成绩好看，持续负载升温后被迫降频「喘气」，速度可能掉一半。手机演示一小段很流畅、连续用几分钟变卡，多半就是热节流——这也是「热节流」的字面意思：为了自我保护先减速降温。</span>最后别忘了端侧存在的理由：数据不出设备是它最大的产品价值，任何为了精度把原始图悄悄上云的设计，都是在拆端侧多模态存在的地基。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>边缘多模态的约束是内存、功耗、算子覆盖三道墙，KV 预算从内存账反推。</li><li>量化分级：LLM int4、编码器 int8、激活随算子支持，逐组件配额。</li><li>节流靠场景变化检测加嵌入复用，省电层自身功耗要低一个量级。</li><li>端侧批为 1、解码吃带宽，投机是常规操作而非可选优化。</li><li>端云分工按置信与上下文判，上行前按预算压图，多轮状态留端侧。</li><li>出处：据 llama.cpp 端侧实践、AWQ（Lin et al., 2023）量化口径与端云协同系统文献整理。</li></ul>',6))])}const g=o(d,[["render",p]]);export{F as __pageData,g as default};
